#!/usr/bin/env python3
"""DCBim v1.0 verifier oracle client.

The verifier for this task runs on a metered oracle server, NOT in this
workspace. You may call it at most 20 times for this task. Each call
uploads your IFC model and returns diagnostic level L1:

  - IFC gate failures: verdict IFC_INVALID or EXTRACTION_FAILED plus
    failing-item tokens only (e.g. "units:not_metre", "DH1:no_body",
    "DH1:multi_polygon", "file:no_buildings", "scale:scale_implausible")
    -- no line numbers, no exception text.
  - Design verdicts (model extracted OK): FEASIBLE | INFEASIBLE |
    SCHEMA_INVALID | GEOMETRY_INVALID with the failing layer and failing
    constraint ids only (composites expand, e.g. "c12[c1,c8]") -- no
    margins, no distances.

Usage:
    python3 oracle_client.py submission/model.ifc

When the budget is exhausted the server answers HTTP 429. Your session is
graded on the BEST design among all oracle-checked models plus your final
submission/model.ifc (ordered by layer reached, then constraint fraction,
then lower objective) -- so every model you check counts.
"""
import base64
import json
import sys
import urllib.request
import urllib.error
from pathlib import Path

ORACLE_URL = "http://172.17.0.1:18200/check"


def main() -> None:
    if len(sys.argv) != 2:
        print(__doc__)
        sys.exit(2)
    ifc_bytes = Path(sys.argv[1]).read_bytes()
    instance_id = json.loads(
        (Path(__file__).resolve().parent / "agent_view.json")
        .read_text(encoding="utf-8"))["id"]
    req = urllib.request.Request(
        ORACLE_URL,
        data=json.dumps({
            "instance": instance_id,
            "ifc_b64": base64.b64encode(ifc_bytes).decode("ascii"),
        }).encode(),
        headers={"Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=120) as resp:
            print(resp.read().decode())
    except urllib.error.HTTPError as e:
        print(e.read().decode())
        sys.exit(1)


if __name__ == "__main__":
    main()

exit_code=0
# graph
nodes=set(graph["nodes"]); check(set(B).issubset(nodes),"graph nodes include every building id")
netids={n["id"]:n for n in nets}
for e in graph["edges"]:
    check(e["u"] in nodes and e["v"] in nodes,"edge nodes exist: "+str(e))
    if e["type"] in ("power_feed","utility_feed"):
        check("via" in e and e["via"] in netids,"edge via existing network: "+str(e))
# required feeds
def has_edge(u,v,t):
    return any((e["u"]==u and e["v"]==v) or (e["u"]==v and e["v"]==u) for e in graph["edges"] if e["type"]==t)
check(has_edge("POC","SUB","utility_feed"),"utility_feed POC->SUB")
check(has_edge("SUB","DH_P1","power_feed"),"power_feed SUB->DH_P1")
check(has_edge("SUB","DH_P2","power_feed"),"power_feed SUB->DH_P2")
# MV connection within 5 m of served structures
def endpoint_near(netid, bname):
    g=netids[netid]["geom"]; poly=B[bname]["poly"]
    return min(point_poly_dist(p[0],p[1],poly) for p in (g[0],g[-1]))<=5+1e-9 or \
           min(seg_poly_dist(g[i],g[i+1],poly) for i in range(len(g)-1))<=5+1e-9
for e in graph["edges"]:
    if e["type"] in ("power_feed","utility_feed"):
        for node in (e["u"],e["v"]):
            if node in B:
                check(endpoint_near(e["via"],node),f"{e['type']} via {e['via']} reaches {node} within 5 m")

# MV under different-phase building
for n in mvs:
    ph=int(n.get("phase",0)); g=n["geom"]
    for nm,b in B.items():
        bph=int(float(b["pset"].get("DCD_Layout",{}).get("Phase",0)))
        if bph==ph: continue
        hit=any(seg_poly_dist(g[i],g[i+1],b["poly"])<1e-9 for i in range(len(g)-1))
        check(not hit,f"MV {n['id']} (phase {ph}) not under different-phase {nm}")

# noise
LW={"DH_P1":83.5,"DH_P2":83.5,"GEN":106.0,"CTP":100.0}
def line_blocked(src, rec, exclude):
    # 3-D LOS through any positive-height building except source; RET excluded (basin not screening)
    sx,sy,sz=src; rx,ry,rz=rec
    for nm,b in B.items():
        if nm in exclude or nm=="RET" or b["top"]<=0: continue
        poly=b["poly"]
        ts=[0.0,1.0]
        for i in range(len(poly)):
            a=poly[i]; c=poly[(i+1)%len(poly)]
            # segment intersection parameter
            dx=rx-sx; dy=ry-sy
            ex=c[0]-a[0]; ey=c[1]-a[1]
            den=dx*ey-dy*ex
            if abs(den)<1e-12: continue
            t=((a[0]-sx)*ey-(a[1]-sy)*ex)/den
            u=((a[0]-sx)*dy-(a[1]-sy)*dx)/den
            if -1e-9<=t<=1+1e-9 and -1e-9<=u<=1+1e-9: ts.append(max(0,min(1,t)))
        ts=sorted(set(round(t,12) for t in ts))
        for j in range(len(ts)-1):
            t=(ts[j]+ts[j+1])/2
            px=sx+(rx-sx)*t; py=sy+(ry-sy)*t; pz=sz+(rz-sz)*t
            if point_in_poly(px,py,poly) and -1e-9<=pz<=b["top"]+1e-9 and pz>=b["zbase"]-1e-9:
                return True,nm,t
    return False,None,None

for phase_filter in (None,1):
    label="all phases" if phase_filter is None else "Phase 1 only"
    for rec in receptors:
        rx,ry=rec["point"]; rz=1.5
        terms=[]
        for nm,L in LW.items():
            b=B[nm]
            if phase_filter is not None and int(float(b["pset"]["DCD_Layout"]["Phase"]))!=phase_filter: continue
            sx,sy=b["centroid"]; sz=max(b["top"],2.0)
            d=math.dist((sx,sy,sz),(rx,ry,rz))
            blocked,who,t=line_blocked((sx,sy,sz),(rx,ry,rz),{nm})
            Lp=L-20*math.log10(d)-11-(10 if blocked else 0)
            terms.append((nm,Lp,blocked,who,d))
        total_db=10*math.log10(sum(10**(x[1]/10) for x in terms)) if terms else 0
        check(total_db<=42.35+1e-9,f"noise {rec['id']} {label} <=42.35 dBA",f"{total_db:.3f} = "+", ".join(f"{n}:{l:.2f}{'(B)' if bl else ''}" for n,l,bl,w,d in terms))
        note("   distances: "+", ".join(f"{n}:{d:.1f}" for n,l,bl,w,d in terms))
        if phase_filter is None:
            # visual check: every sampled generator-yard point must be screened from the receptor
            gp=B["GEN"]["poly"]; margins=[]
            for i in range(len(gp)):
                for frac in (0.0,0.25,0.5,0.75):
                    x=gp[i][0]+(gp[(i+1)%len(gp)][0]-gp[i][0])*frac
                    y=gp[i][1]+(gp[(i+1)%len(gp)][1]-gp[i][1])*frac
                    for ztarget in (0.5,B["GEN"]["top"]):
                        blocked,who,t=line_blocked((x,y,ztarget),(rx,ry,1.7),{"GEN"})
                        if not blocked:
                            margins.append((round(x,2),round(y,2),ztarget))
            check(not margins,f"GEN not visible from {rec['id']} (full footprint)",f"{len(margins)} unblocked sample(s)")
            margins_p1=[]
            for i in range(len(gp)):
                for frac in (0.0,0.25,0.5,0.75):
                    x=gp[i][0]+(gp[(i+1)%len(gp)][0]-gp[i][0])*frac
                    y=gp[i][1]+(gp[(i+1)%len(gp)][1]-gp[i][1])*frac
                    for ztarget in (0.5,B["GEN"]["top"]):
                        blocked,who,t=line_blocked((x,y,ztarget),(rx,ry,1.7),{"GEN","DH_P2"})
                        if not blocked: margins_p1.append((round(x,2),round(y,2),ztarget))
            check(not margins_p1,f"GEN not visible from {rec['id']} (Phase 1 only)",f"{len(margins_p1)} unblocked sample(s)")

print("\nRESULT:", "ALL CHECKS PASS" if not fails else f"{len(fails)} FAILURES")
for f in fails: print(" -",f)
sys.exit(0 if not fails else 1)

