nodes=set(graph["nodes"]); check(set(B).issubset(nodes),"graph nodes include every building id")
netids={n["id"]:n for n in nets}
for e in graph["edges"]:
    check(e["u"] in nodes and e["v"] in nodes,"edge nodes exist: "+str(e))
    if e["type"] in ("power_feed","utility_feed"):
        check("via" in e and e["via"] in netids,"edge via existing network: "+str(e))
# required feeds
def has_edge(u,v,t):
    return any((e["u"]==u and e["v"]==v) or (e["u"]==v and e["v"]==u) for e in graph["edges"] if e["type"]==t)
check(has_edge("POC","SUB","utility_feed"),"utility_feed POC->SUB")
check(has_edge("SUB","DH_P1","power_feed"),"power_feed SUB->DH_P1")
check(has_edge("SUB","DH_P2","power_feed"),"power_feed SUB->DH_P2")
# MV connection within 5 m of served structures
def endpoint_near(netid, bname):
    g=netids[netid]["geom"]; poly=B[bname]["poly"]
    return min(point_poly_dist(p[0],p[1],poly) for p in (g[0],g[-1]))<=5+1e-9 or \
           min(seg_poly_dist(g[i],g[i+1],poly) for i in range(len(g)-1))<=5+1e-9
for e in graph["edges"]:
    if e["type"] in ("power_feed","utility_feed"):
        for node in (e["u"],e["v"]):
            if node in B:
                check(endpoint_near(e["via"],node),f"{e['type']} via {e['via']} reaches {node} within 5 m")

# MV under different-phase building
for n in mvs:
    ph=int(n.get("phase",0)); g=n["geom"]
    for nm,b in B.items():
        bph=int(float(b["pset"].get("DCD_Layout",{}).get("Phase",0)))
        if bph==ph: continue
        hit=any(seg_poly_dist(g[i],g[i+1],b["poly"])<1e-9 for i in range(len(g)-1))
        check(not hit,f"MV {n['id']} (phase {ph}) not under different-phase {nm}")

